def strlen_recursive(string: str) -> int:
    """ Return length of given string using recursion
    >>> strlen_recursive('')
    0
    >>> strlen_recursive('abc')
    3
    """
    if string == '':
        return 0
    return 1 + strlen_recursive(string[1:])

def find_triples_sum_to_zero(l: list):
    """
    find_triples_sum_to_zero takes a list of integers as an input.
    It returns a list of tuples, each containing three distinct elements from the list that sum to zero.
    If no such triple exists, returns an empty list.
    """
    n = len(l)
    if n < 3:
        return []

    # Sort to use two-pointer technique and avoid duplicate triples
    l_sorted = sorted(l)
    triples = []

    for i in range(n - 2):
        # Skip duplicate first elements
        if i > 0 and l_sorted[i] == l_sorted[i-1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = l_sorted[i] + l_sorted[left] + l_sorted[right]
            if total == 0:
                triples.append((l_sorted[i], l_sorted[left], l_sorted[right]))
                # Skip duplicates for left and right
                while left < right and l_sorted[left] == l_sorted[left+1]:
                    left += 1
                while left < right and l_sorted[right] == l_sorted[right-1]:
                    right -= 1
                left += 1
                right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1
    return triples

def decode_shift(s: str) -> str:
    """
    Returns decoded string by shifting every character back by 5 in the alphabet.
    This reverses the encoding performed by encode_shift.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def strictly_monotonic(l: list):
    """Return True if list elements are strictly monotonically increasing or decreasing.
    >>> strictly_monotonic([1, 2, 4, 20])
    True
    >>> strictly_monotonic([1, 20, 4, 10])
    False
    >>> strictly_monotonic([1, 2, 2, 3])
    False
    """
    if len(l) <= 2:
        return True

    # Determine direction from first two elements
    if l[0] < l[1]:
        # Check strictly increasing
        return all(l[i] < l[i+1] for i in range(len(l)-1))
    elif l[0] > l[1]:
        # Check strictly decreasing
        return all(l[i] > l[i+1] for i in range(len(l)-1))
    else:
        # First two elements equal - can't be strictly monotonic
        return False

