def words_in_sentence(sentence):
    """
    Returns a string containing words from the input sentence whose lengths are prime numbers,
    preserving the original order.
    """
    def is_prime(n):
        """Return True if n is a prime number, else False."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Split the sentence into words
    words = sentence.split()
    # Filter words whose length is prime
    prime_words = [word for word in words if is_prime(len(word))]
    # Join them back with spaces
    return " ".join(prime_words)

def bf(planet1, planet2):
    '''
    Returns a tuple of planets whose orbits lie strictly between the orbits
    of planet1 and planet2, sorted by proximity to the Sun.
    Returns an empty tuple if either planet name is invalid.
    '''
    # Ordered list of planets from closest to farthest from the Sun
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Check if both planet names are valid
    if planet1 not in planets or planet2 not in planets:
        return ()

    # Get indices
    idx1 = planets.index(planet1)
    idx2 = planets.index(planet2)

    # Determine the range (exclusive of the endpoints)
    start = min(idx1, idx2) + 1
    end = max(idx1, idx2)

    # If no planets in between, return empty tuple
    if start >= end:
        return ()

    # Return the planets in the range as a tuple
    return tuple(planets[start:end])

def solve(s):
    """
    You are given a string s.
    If s[i] is a letter, reverse its case from lower to upper or vice versa.
    Otherwise, keep it as it is.
    If the string contains no letters, reverse the entire string.
    """
    # Check if string contains any letters
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        # If no letters, reverse the entire string
        return s[::-1]
    else:
        # Otherwise, reverse the case of each letter
        result = []
        for char in s:
            if char.isalpha():
                if char.islower():
                    result.append(char.upper())
                else:
                    result.append(char.lower())
            else:
                result.append(char)
        return ''.join(result)
